"""Build bilingual local hardware pages and engineering-cycle fragments from release data.
No upload or publication. Run after optics and airflow have finished.
"""
from pathlib import Path
import json,html,re,hashlib
from simulation_supplement import section as simulation_supplement
P=Path(__file__).resolve().parent;ROOT=P.parent
def load(p):return json.loads((ROOT/p).read_text(encoding='utf-8'))
def esc(s):return html.escape(str(s))
def link(p,t):return f'<a href="{p}">{t}</a>'
def fig(p,c):return f'<figure><a href="{p}"><img src="{p}" alt="{esc(c)}" loading="lazy"></a><figcaption>{c}</figcaption></figure>'
def table(headers,rows):return '<div class="scroll"><table><thead><tr>'+''.join(f'<th>{h}</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{v}</td>' for v in r)+'</tr>' for r in rows)+'</tbody></table></div>'
STYLE='''*{box-sizing:border-box}body{margin:0;background:#f2f5f8;color:#162b38;font:17px/1.75 system-ui,"Microsoft JhengHei",sans-serif}a{color:#087982;text-underline-offset:4px}header{background:#102935;color:#fff;padding:64px max(6vw,24px)}header p{max-width:950px;color:#d6e4ed}header h1{font-size:clamp(32px,5vw,58px);line-height:1.1;max-width:1100px;margin:18px 0}header a{color:#8be1d8}.eyebrow{text-transform:uppercase;letter-spacing:.16em;font-size:13px;font-weight:750}.status{display:inline-block;border:1px solid #d8aa4d;background:#423721;color:#ffe5a8;padding:5px 12px;border-radius:8px;font-size:14px}nav{padding:14px 6vw;background:white;display:flex;gap:22px;flex-wrap:wrap;border-bottom:1px solid #d5e1e8}main{max-width:1180px;margin:auto;padding:24px}section{margin:30px 0;padding:32px;background:white;border-radius:16px;border:1px solid #dfe7ec}h2{font-size:29px;line-height:1.3;margin-top:0}h3{font-size:21px}p{max-width:1020px}figure{margin:25px 0}figure img{width:100%;height:auto;display:block;border:1px solid #d8e2e8;border-radius:10px}figcaption{font-size:14px;color:#536977;margin-top:9px}video{width:100%;border-radius:12px;background:#10202a}table{width:100%;border-collapse:collapse;font-size:15px}th{text-align:left;background:#eaf1f5}td,th{padding:12px;border-bottom:1px solid #dfe7ec;vertical-align:top}.scroll{overflow:auto}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px}.card{background:#edf6f6;border-left:4px solid #16898c;padding:18px;border-radius:6px}.card b{font-size:23px;display:block}.note{border-left:4px solid #d1a040;padding:12px 18px;background:#fff6e4}.downloads{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:12px}.downloads a{background:#edf3f7;padding:14px;border-radius:8px;display:block}footer{padding:30px 6vw;color:#536977;font-size:14px}code{background:#edf2f5;padding:2px 5px;border-radius:4px}@media(max-width:600px){main{padding:8px}section{padding:20px}header{padding:38px 22px}table{font-size:13px}}'''
PRINTS=[('01_base_BLACK.stl','Base / fan cradle / access windows','底座／風扇座／接孔開口'),('02_black_hood_BLACK.stl','Black optical carrier and hood','黑色光學井座與遮光罩'),('03_gas_lid_BLACK.stl','Gas lid with integral deflector','氣蓋與一體導流平台'),('04_well_NE_CLEAR.stl','NE flat-bottom well','NE 平底井'),('05_well_NW_CLEAR.stl','NW flat-bottom well','NW 平底井'),('06_well_SW_CLEAR.stl','SW flat-bottom well','SW 平底井'),('07_well_SE_CLEAR.stl','SE flat-bottom well','SE 平底井'),('08_gas_compression_plate_BLACK.stl','Removable four-well compression plate','可拆式四井壓板')]
def build():
 o=load('02_simulation/optics/results/summary.json');maps=load('02_simulation/optics/results/maps_summary.json');a=load('02_simulation/airflow/selection.json')
 op=load('02_simulation/airflow/operating_sweep_summary.json');candidate=op['chosen_conditional_point'];baseline=load('02_simulation/airflow/gas_transport_results/shelf_w8_e0p2_D10_dx0.4_dt0.5.json');selected_checks=op['numerical_checks']
 cases={r['case']:r for r in o['cases']};ne=cases['ideal_NE'];target=o['intended_well_fraction'];fine=sorted(a['mesh_refinement'],key=lambda x:x['dx_mm'])[0]
 reduction=(1-fine['J_ratio'])*100;speed=(1-fine['speed_ratio'])*100
 rcase=a['selected_case'];bo=a['CAD_solid_box_mm'];percent_volume=(1-108*108*66/(114*109*91))*100
 values=dict(NE_nW=ne['green_nW'],NE_SE_nW=ne['green_SE_nW'],target_pct_min=min(target)*100,target_pct_max=max(target)*100,condition=o['condition_number'],floor_NE=maps['floor_mean_uW_mm2'][0],floor_CV_NE=maps['floor_CV'][0]*100,blue_unfiltered=cases['no_filter_rejection']['blue_nW'],blue_OD3=cases['filter_OD3']['blue_nW'],CFD_case=rcase,CFD_finest_mm=fine['dx_mm'],CFD_J_reduction_pct=reduction,CFD_speed_reduction_pct=speed)
 values.update(gas_baseline_Q_mL_min=1,gas_baseline_NE_t90_s=baseline['t90_s']['NE_near_liquid'],operating_Q_mL_min=candidate['Q_mL_min'],operating_worst_t90_s=candidate['worst_t90_s'],operating_selected_grid_t90_s=selected_checks['selected_point_grid']['worst_t90_s'],operating_selected_half_dt_t90_s=selected_checks['selected_point_timestep']['worst_t90_s'],operating_port_Re=candidate['port_Re'],operating_chamber_drop_Pa=candidate['chamber_pressure_drop_Pa'])
 (P/'numerical_sources.json').write_text(json.dumps(dict(values=values,optics='02_simulation/optics/results/summary.json',optical_maps='02_simulation/optics/results/maps_summary.json',airflow='02_simulation/airflow/selection.json',operating_sweep='02_simulation/airflow/operating_sweep_summary.json',software_evidence='03_software/evidence/',validation_plan='07_validation/Validation_Plan_EN.md',status='computational results; no physical prototype validation'),indent=2),encoding='utf-8')
 for lang in ['EN','ZH']:
  en=lang=='EN';T=lambda x,y:x if en else y
  title=T('AeroSense · from PCB to a reproducible instrument','AeroSense：從 PCB 到可重現的儀器設計')
  sections=[]
  def sec(id,title,body):sections.append(f'<section id="{id}"><h2>{title}</h2>{body}</section>')
  sec('hardware-architecture',T('A portable reader for living-cell fluorescence','可攜式活細胞螢光讀取器'),T('''<p>AeroSense is being developed to measure GCaMP fluorescence from four HEK293T sensor wells exposed to one shared gas sample. Four blue LEDs are frequency-tagged, and one photodiode records their combined optical response. The ESP32 handles excitation and acquisition; a phone provides control and displays data. A future trained model may analyze validated measurements on a phone or cloud service.</p><p>The hardware addresses a practical synthetic-biology need: repeatable positioning, optical measurement, removable sample wells, and traceable acquisition in one documented platform. Cell responses, odor classification and real-world detection performance have not yet been established by this package.</p>''','''<p>AeroSense 以四個 HEK293T 感測井接觸同一股樣本氣體，讀取 GCaMP 螢光。四顆藍光 LED 使用不同頻率，一顆 PD 收集混合光訊號；ESP32 負責打光與擷取，手機負責控制及顯示資料。未來經過驗證與訓練的模型，可在手機或雲端分析量測結果。</p><p>這個硬體要解決的是合成生物學中的實際操作問題：固定樣本與光學位置、可更換的井、可追溯的量測，以及可供其他團隊重現的組裝文件。本資料包尚未證明細胞對氣味的反應、分類準確率或現場檢測效能。</p>''')+'<div class="cards">'+''.join(f'<div class="card"><b>{x}</b>{y}</div>' for x,y in [('108 × 108 × 66 mm',T('Nominal enclosure envelope','外殼名義包絡')),('4 + 1',T('Four LEDs, one offset PD','四顆 LED、一顆偏心 PD')),('8',T('Prints: four black + four clear','列印件：四黑＋四透明')),('100 µL',T('Nominal liquid per well','每井名義液量'))])+'</div>')
  sec('mechanical-package',T('Compact, serviceable, and registered to the LEDs','縮小體積、可開合、以 LED 定位'),T(f'''<p>The enclosure integrates a 40 × 40 × 10 mm fan cradle below the PCB, service openings for USB-C and the board switch, and a removable gas lid. Four flat-bottom wells fit inside one opaque carrier with a minimum 1.2 mm central web. The lower 1.7 mm optical band remains exposed; the upper walls are black-sleeved. A removable compression plate loads the four well-rim seals before the outer lid closes.</p><p>The 108 × 108 × 66 mm envelope is {percent_volume:.1f}% smaller by bounding-box volume than the preceding 114 × 109 × 91 mm layout. This is a CAD size comparison, not a measured mass, thermal or portability result. Clear wells have 4 × 2.8 mm internal sections, a 0.5 mm flat floor and 12.5 mm internal height: 100 µL nominal and 140 µL geometric brim capacity. Leave headspace.</p><p>The centers follow the LED geometry (±3.3, ±2.65 mm); the PD sensitive-area proxy is offset by (0, −0.4) mm. The model does not assume that the PD package center is its optical center. Board-side mirroring, populated component heights and connector positions still require manufacturer or bench confirmation.</p>''',f'''<p>底座整合 PCB 下方的 40 × 40 × 10 mm 風扇座、USB-C 與板載開關維修開口，以及可拆氣蓋。四個平底井裝入同一個黑色井座，中央隔牆最薄 1.2 mm；底部 1.7 mm 保留光學通道，上方四周包黑。可拆壓板先壓緊四個井口的密封片，再關閉外氣蓋。</p><p>相較原先 114 × 109 × 91 mm，108 × 108 × 66 mm 的包絡體積減少 {percent_volume:.1f}%。這是 CAD 尺寸比較，並非實測重量、散熱或攜帶性結果。透明井內腔 4 × 2.8 mm、平底厚 0.5 mm、內高 12.5 mm；名義液量 100 µL，幾何滿杯量 140 µL，使用時必須保留氣相空間。</p><p>四井中心依 LED 定位在 (±3.3, ±2.65) mm；PD 感光區代理中心為 (0, −0.4) mm，沒有把 PD 封裝中心當成光學中心。PCB 底視鏡像、實際零件高度與接孔位置仍需廠商或實板確認。</p>''')+fig('../09_engineering_sources/CAD/drawings/assembly_exploded.png',T('Assembly overview. The exact printable inventory is listed below.','組裝總覽；實際列印件清單如下。'))+fig('../09_engineering_sources/CAD/drawings/base_fan_ports.png',T('Integrated fan cradle and connector service openings. Drawing dimensions are nominal.','一體風扇座與接孔維修開口；圖面為名義尺寸。'))+fig('../09_engineering_sources/CAD/drawings/optical_registration.png',T('LED-based well registration and provisional off-center detector datum.','依 LED 定位的井中心，以及暫定偏心 PD 基準。')))
  rows=[]
  for fn,e,z in PRINTS:rows.append([link('../01_print/'+fn,fn),e if en else z,T('Rigid PC-GF-like Black','Rigid PC-GF-like Black 黑色') if 'BLACK' in fn else 'Aqua-Clear Plus'])
  sec('reader-assembly',T('Print this set, then follow the assembly manual','請列印這一組，再依手冊組裝'),table(T(['STL file','Function','Resin'],['STL 檔案','功能','樹脂']),rows)+T('''<p>This selected print set uses black structural parts and clear wells; Aqua 8K Gray is not used. Check fit and light leakage on the actual operating parts. Clear-resin wells are for cell-free fit and optical trials until material compatibility, extractables, optical transmission and autofluorescence have been tested. A clear appearance does not establish culture compatibility.</p><p>The fan cradle and gas deflector are integral features. The four wells and compression plate remain removable because replacing samples, loading seals and cleaning require access. Removing these interfaces to lower the part count would remove intended functions.</p>''','''<p>本組固定使用黑色結構件與透明井，不使用 Aqua 8K Gray。直接在正式零件上檢查尺寸配合與漏光。透明樹脂井先用於無細胞試裝與光學測試，之後仍須確認材料相容性、浸出物、穿透率及自體螢光。外觀看起來透明，不等於適合培養細胞。</p><p>風扇座與導流平台已一體化。四個井與壓板保留可拆，是為了更換樣本、壓緊密封片與清潔；不能只為減少件數而取消必要的操作介面。</p>''')+link(f'../04_manuals/Assembly_Manual_{lang}.pdf',T('Read the illustrated assembly manual →','閱讀圖解組裝手冊 →')))
  sec('optical-question',T('A physically possible path is not yet a validated measurement','光路可行，不等於量測已經成立'),T(f'''<p>The ideal-material model traces excitation through flat-bottom wells, then isotropic 520 nm emission from a 20 µm bottom cell layer to the finite detector. It includes refractive interfaces, total internal reflection, the PD seal and filter, component obstructions, black surfaces and optional scattering. Perfectly clear resin is the baseline requested here; no purple tint is assumed.</p><p>At an assumed 500 µW LED-on power, 470 nm excitation, cell absorption 0.5 mm⁻¹ and quantum yield 1, the NE case delivers <strong>{ne['green_nW']:.3f} ± {ne['green_SE_nW']:.3f} nW</strong> to the ideal PD (mean ± Monte Carlo standard error across three seeds). These are conditional calculations, not measured GCaMP output. Absorption, expression, quantum yield, excitation power, filter transmission and electronic noise remain experimental inputs.</p><p>Across the four LEDs, the intended well supplies {min(target)*100:.1f}–{max(target)*100:.1f}% of modeled fluorescence at the detector. The rest comes from other wells. The transfer matrix has condition number {o['condition_number']:.2f} under these assumptions. This supports testing calibrated unmixing; it does not establish four independent channels. A minimum 1.2 mm black web does not eliminate paths through the shared bottom optical band.</p>''',f'''<p>理想材料模型追蹤激發光穿過平底井，再由底部 20 µm 細胞層產生等向性 520 nm 螢光到有限面積的 PD。模型包含折射、全反射、PD 密封圈與濾光片、元件阻擋、黑色表面，以及額外的散射案例。本次基準依需求採理想透明樹脂，沒有加入紫色色偏。</p><p>在 LED 開啟光功率 500 µW、470 nm 激發、細胞吸收係數 0.5 mm⁻¹、量子產率 1 的假設下，NE LED 案例到達理想 PD 的綠光為 <strong>{ne['green_nW']:.3f} ± {ne['green_SE_nW']:.3f} nW</strong>（三個隨機種子的平均 ± 蒙地卡羅標準誤）。這是條件式預測，不是實測 GCaMP 輸出；吸收、表現量、量子產率、實際 LED 功率、濾光與電子雜訊都還需要量測。</p><p>四顆 LED 對應的目標井，分別提供 PD 所收螢光的 {min(target)*100:.1f}–{max(target)*100:.1f}%；其餘來自其他井。此假設下混合矩陣條件數為 {o['condition_number']:.2f}，支持後續測試校正解混，但不代表四個獨立通道。1.2 mm 黑色隔牆無法取消底部共用光路造成的串擾。</p>''')+fig('../02_simulation/optics/figures/03_well_transfer.png',T('Cell-layer LED-by-well transfer. Rows follow physical LED positions; columns follow source wells.','細胞層的 LED × 井混合矩陣；列為 LED 實體位置，欄為螢光來源井。')))
  sec('well-floor-results',T('Flat floors help geometry, but do not guarantee uniform light','平底有利定位，但不會自動讓光均勻'),T(f'''<p>The NE floor receives a modeled mean {maps['floor_mean_uW_mm2'][0]:.3f} µW/mm²; its spatial coefficient of variation is {maps['floor_CV'][0]*100:.1f}%. This directional irradiance map scores upward power crossing the floor, not tissue fluence. The collection map uses 224 point sources and 65,536 packets per point. A side-emitting LED and finite off-center PD make illumination and collection position-dependent even with a perfectly flat well.</p><p>Published tissue-photometry maps often show three-dimensional fluence or normalized excitation in scattering tissue. This cartridge contains clear walls, liquid, a cell layer and black boundaries. Its source, geometry, scoring quantity and normalization differ, so reproducing a literature figure's visual shape is not a correctness test. Compare like quantities and retain units.</p>''',f'''<p>NE 井底的平均模擬照度為 {maps['floor_mean_uW_mm2'][0]:.3f} µW/mm²，空間變異係數為 {maps['floor_CV'][0]*100:.1f}%。這張圖計算向上穿過井底的功率，不是組織內的 fluence。收光圖使用 224 個點光源、每點 65,536 個光子封包。即使井底完全平坦，側向 LED 與有限且偏心的 PD 仍會造成位置差異。</p><p>文獻的組織光學圖常呈現散射組織中的三維 fluence 或正規化激發強度；本設計是透明壁、液體、細胞底層及黑色邊界。光源、幾何、計分物理量及正規化方式都不同，因此不能以圖形看起來是否相同判斷正確性。應比較相同物理量並保留單位。</p>''')+fig('../02_simulation/optics/figures/02_floor_maps.png',T('Directional floor irradiance and position-dependent collection.','井底方向性照度與位置相關的收光效率。'))+fig('../02_simulation/optics/figures/04_detector_angles.png',T('Detector arrival-angle distribution; real interference-filter response remains unmeasured.','到達 PD 的角度分布；實際干涉濾片的角度響應尚未量測。')))
  sec('multiplexing',T('Frequency recovery does not remove synchronous reflected light','頻率解調不能消除同頻反射光'),T(f'''<p>The synthetic demonstration uses 41/67/89/113 Hz, 25% LED duty and a 4 kHz sampling clock. Its amplitudes use the Monte Carlo fluorescence gains. Excitation leakage is an explicit same-frequency background: a lock-in detects it together with fluorescence. In the NE scenario, modeled blue power is {cases['no_filter_rejection']['blue_nW']:.3f} nW without rejection and {cases['filter_OD3']['blue_nW']:.5f} nW with the idealized OD3 absorptive filter. A real interference filter may shift at oblique incidence; the stated OD is not a measured installed result.</p><p>The animation slows a physical 0.2-second LED waveform by 100×. Moving photon dots are schematic progress along sampled paths, not photon flight times. Mirrored paths illustrate other channels; the frequency-recovery plot uses a separate two-second synthetic record. These are explanatory views, not measured videos or an electronics timing qualification.</p>''',f'''<p>合成示範使用 41／67／89／113 Hz、25% LED duty、4 kHz 取樣，螢光增益取自蒙地卡羅结果。漏進 PD 的激發光與 LED 同頻，lock-in 會把它與螢光一起解調。NE 案例未阻擋藍光時為 {cases['no_filter_rejection']['blue_nW']:.3f} nW，理想化 OD3 吸收型濾片時為 {cases['filter_OD3']['blue_nW']:.5f} nW。實際干涉濾片可能因入射角而位移，不能把名目 OD 直接當成裝機後量測值。</p><p>影片將 0.2 秒的實體 LED 波形放慢 100 倍；光點只是沿抽樣路徑移動的示意，並非真實光子飛行時間。其他通道以鏡像路徑說明，頻率復原圖則使用另外兩秒的合成訊號。這是原理解釋，不是實拍影片，也不是電子時序的實測認證。</p>''')+f'<video controls preload="metadata" poster="../02_simulation/optics/figures/05_frequency_recovery.png"><source src="../02_simulation/optics/optical_slow_motion.mp4" type="video/mp4"></video><p>{link("../02_simulation/optics/optical_slow_motion.gif",T("GIF alternative","GIF 替代版本"))}</p>'+fig('../02_simulation/optics/figures/05_frequency_recovery.png',T('Recovered synthetic modulation includes fluorescence and synchronous blue leakage.','合成訊號解調同時包含螢光與同頻藍光漏光。')))
  sec('gas-path-results',T('Redirect the inlet jet; do not aim for turbulence','改變進氣方向，而不是追求亂流'),T(f'''<p>The gas model compares open, perforated, wall, hood and shelf configurations using the final common plenum. At the original 1 mL/min reference flow, the inlet Reynolds number is below one: this is laminar flow. A perforated plate can form several narrow jets; simply making holes does not guarantee lower velocity at cells. The chosen integrated candidate is <strong>{esc(rcase)}</strong>, with solid bounds {bo['minimum']} to {bo['maximum']} mm.</p><p>At the finest {fine['dx_mm']:.2f} mm grid, the selected shelf changes the maximum-well downward momentum proxy by <strong>{reduction:.1f}% reduction</strong> relative to an open plenum. The near-liquid 95th-percentile gas-speed change is {speed:.1f}% reduction. These are geometry-specific numerical comparisons. Mesh sensitivity and the tradeoff in circulation balance are reported; this is a practical candidate, not a globally proven optimum.</p><p>The proxy is evaluated in the gas and is not cell shear stress or viability. The model does not solve liquid motion, odor dissolution, receptor binding or biological survival. Shared gas means the wells are not gas-isolated. An always-open filtered exhaust during closure lets displaced air escape; the lid must not act as a sealed piston.</p>''',f'''<p>氣流模型以最終共用氣室比較開放氣室、孔板、直立擋板、罩式與平台式導流。在原始 1 mL/min 基準下入口 Reynolds number 小於 1，屬於層流。孔板可能把氣流變成數個小噴流，打孔本身不保證細胞附近速度下降。選定的一體候選為 <strong>{esc(rcase)}</strong>，实体範圍 {bo['minimum']} 至 {bo['maximum']} mm。</p><p>最細 {fine['dx_mm']:.2f} mm 網格下，導流平台相較空氣室，使四井中最大的向下動量代理量<strong>下降 {reduction:.1f}%</strong>；接近液面的氣速第 95 百分位下降 {speed:.1f}%。這是特定幾何的數值比較。報告保留網格敏感度與四井循環均衡的代價，因此稱為實用候選，不宣稱全域最佳。</p><p>此指標位於氣相，不等於細胞剪切力或存活率。模型沒有解液體流動、氣味溶解、受體結合或細胞生長。共用氣路也代表四井不具氣相隔離。關蓋時保持經過濾的排氣路暢通，讓被擠出的空氣離開，避免蓋子形成密閉活塞。</p>''')+fig('../02_simulation/airflow/figures/design_comparison.png',T('Final-geometry gas-path sweep. Read the uncertainty and mesh refinement alongside the ranking.','最終幾何的氣路掃參數；排名必須與不確定性及網格細化一起閱讀。'))+f'<video controls preload="metadata" poster="../02_simulation/airflow/figures/velocity_sections.png"><source src="../02_simulation/airflow/airflow_comparison.mp4" type="video/mp4"></video>')
  sec('gas-operation',T('A conditional operating point without changing the STL','不改STL的條件式操作流量'),T(f'''<p>The original 1 mL/min case remains a reference: near-liquid NE gas t90 is {values['gas_baseline_NE_t90_s']:.2f} s at Dgas=10 mm²/s. A new fixed-shelf study contains {op['screening_scalar_solves']} operating conditions and {op['validation_scalar_solves']} numerical checks. The lowest sampled candidate meeting the provisional worst-well/worst-D gas t90≤60 s target is <strong>{candidate['Q_mL_min']:g} mL/min</strong>, with t90={candidate['worst_t90_s']:.2f} s across the four wells and assumed Dgas=5/10/20 mm²/s.</p><p>At the selected point, the finer-grid result is {values['operating_selected_grid_t90_s']:.2f} s and the half-timestep result is {values['operating_selected_half_dt_t90_s']:.2f} s. Q2.5 gives about60.04 s and is numerically borderline, not proven physically inadequate. The near-liquid gas-speed cap0.01 mm/s is an engineering comparison limit, not a cell-injury threshold. This is a tested numerical candidate, not a global optimum or a measured cell response.</p><p>Use one regulated downstream pump and measure approximately{candidate['Q_mL_min']:g} mL/min through the assembled path. At the same pressure/temperature reference, steady inlet and outlet volume flows are equal; do not impose two independent unequal pump settings. Port Re is {candidate['port_Re']:.3f}; modeled chamber drop is {candidate['chamber_pressure_drop_Pa']:.5f} Pa, excluding filters and external tubing. The current UI does not control or sense actual gas flow. The existing gas movie remains the 1 mL/min baseline.</p>''',f'''<p>原始 1 mL/min 保留為基準：Dgas=10 mm²/s時，NE井近液面氣相t90為 {values['gas_baseline_NE_t90_s']:.2f} 秒。新的固定平台研究包含 {op['screening_scalar_solves']} 組操作條件及 {op['validation_scalar_solves']} 組數值檢查。在四井及假設Dgas=5／10／20 mm²/s中，以最慢氣相t90≤60秒為暫定目標，符合條件的最低取樣候選為 <strong>{candidate['Q_mL_min']:g} mL/min</strong>，最慢t90為 {candidate['worst_t90_s']:.2f} 秒。</p><p>選定點的細網格結果為 {values['operating_selected_grid_t90_s']:.2f} 秒，時間步減半為 {values['operating_selected_half_dt_t90_s']:.2f} 秒。Q2.5約60.04秒，屬數值邊界，不能說實物一定不合格。近液面氣速0.01 mm/s只是工程比較上限，並非細胞傷害門檻。這是經數值檢查的條件式候選，不是全域最佳，也不是實測細胞反應。</p><p>以一個受控的下游抽氣泵，量測整條組裝氣路約 {candidate['Q_mL_min']:g} mL/min；同一壓溫基準下穩態進出體積流量相同，不要各設不同的進氣／抽氣流量。入口Re為 {candidate['port_Re']:.3f}，氣室模擬壓降 {candidate['chamber_pressure_drop_Pa']:.5f} Pa不含濾嘴與外部管路；目前UI沒有實際氣流控制或感測。既有氣流影片仍是1 mL/min基準。</p>''')+fig('../02_simulation/airflow/figures/operating_delivery.png',T('Computed gas-side t10/t50/t90; this does not establish exposure at submerged cells.','計算的氣側t10／t50／t90；不代表浸液細胞已接收到刺激。'))+fig('../02_simulation/airflow/figures/operating_pareto.png',T('Discrete delivery-time versus gas-speed tradeoff; the ring marks the conditional operating candidate.','離散的供氣時間與氣速取捨；圓圈標示條件式操作候選。'))+'<p>'+link('../02_simulation/airflow/operating_sweep_3d.html',T('Explore the actual computed operating points','探索實際計算的操作點'))+' · '+link('../02_simulation/airflow/Flow_Operation_'+lang+'.md',T('Read assumptions, pump arrangement and numerical checks','閱讀假設、泵配置與數值檢查'))+'</p>')
  sec('electronics-bridge',T('One acquisition path, explicit data states','單一資料流程，清楚區分資料狀態'),T('''<p>The ESP32 gates GPIO 25/26/27/32 at 41/67/89/113 Hz. The proposed acquisition uses a 4 kHz sample clock and a two-second I/Q analysis block. GPIO assignments come from the schematic; the physical LED quadrant mapping must be checked for bottom-view mirroring. The analog path uses a photodiode, transimpedance amplifier and ADS8866 ADC. Firmware compilation and synthetic tests do not prove that the physical board works.</p><p>The phone interface provides connection, status, acquisition settings, measurements and calibration/normalization workflows. Setup instructions separate demonstration data from live hardware data. No trained, validated odor-classification network is delivered or claimed. Keep raw data, timestamps, configuration, calibration IDs and firmware versions with every acquisition.</p>''','''<p>ESP32 以 GPIO 25／26／27／32 對應 41／67／89／113 Hz；擬用 4 kHz 取樣時脈及兩秒 I/Q 分析區塊。GPIO 依電路圖核對，LED 實體象限仍須確認底視圖鏡像。類比鏈為 PD、跨阻放大器與 ADS8866 ADC。韌體可以編譯、合成測試可以通過，都不代表未驗證的實板已能運作。</p><p>手機介面包含連線、狀態、量測設定、結果與校正／正規化流程。設定手冊明確區分示範資料與硬體資料。本資料包沒有宣稱已訓練並驗證的氣味分類網路。每次量測應保存原始資料、時間、設定、校正 ID 與韌體版本。</p>''')+link(f'../04_manuals/Operation_and_Setup_{lang}.pdf',T('Read setup, controls and calibration instructions →','閱讀設定、按鍵與校正流程 →')))
  sec('measured-correction',T('Measured correction preserves the original data','以實測空白校正，保留原始資料'),T('''<p>The phone UI optionally subtracts a separately measured, cell-free illuminated blank in complex I/Q space, then uses a fluorescence reference for signed phase projection. Living-cell F0 is a separate biological baseline. The illuminated blank already contains dark background, so dark is not subtracted a second time. Raw I/Q, corrected unsmoothed values, calibration IDs and sample labels remain exportable.</p><p>Optional timestamp-based EMA is for display averaging; quantitative comparisons retain unsmoothed block values. Removing a stable mean does not remove random noise, clipping or changing same-frequency interference. No simulated anti-waveform or automatic Monte Carlo unmixing is applied. Software evidence is linked by file rather than a frozen test count; compilation and synthetic tests do not demonstrate a working physical PCB.</p>''','''<p>手機UI可選擇在複數I/Q空間扣除獨立量測、無細胞且LED開啟的空白，再用螢光參考品決定有正負號的相位投影。活細胞F0另作生物基線；亮燈空白已包含暗背景，不再重複扣暗。原始I/Q、未平滑的校正值、校正ID與樣本標籤皆保留供匯出。</p><p>可選的時間戳記EMA用於顯示平均；定量比較保留未平滑的區塊值。扣除穩定平均不能去除隨機雜訊、飽和或會變化的同頻干擾。本流程沒有任意加模擬反波，也不自動套用蒙地卡羅解混矩陣。軟體證據以目前檔案連結呈現，不固定抄寫測試數量；編譯與合成測試不等於實板已能運作。</p>''')+'<div class="downloads">'+''.join(link(p,t) for p,t in [(f'../03_software/guides/Measured_Correction_{lang}.md',T('Measured-correction controls and workflow','實測校正按鍵與流程')),('../03_software/evidence/software_tests.json',T('Current host-test results','目前主機測試結果')),('../03_software/evidence/measured_correction_tests.json',T('Measured-correction tests','實測校正測試')),('../03_software/evidence/ui_integration_tests.json',T('UI integration tests and scope','UI整合測試及範圍'))])+'</div>')
  sec('cost-and-reproduction',T('A complete inventory, with unknown prices left visible','完整列項，未知價格保持可見'),T('''<p>The BOM separates printed STL parts, PCB components and additional purchases. The supplied PCB quote is NT$131,250 for two boards, including design and setup. NT$65,625 is an allocated average from that quote, not a scalable production unit price. Optical filters and compatibility-critical materials must not be assigned invented prices or removed only to make the total look lower.</p><p>Cost reduction comes from integral fan and gas features, one shared gas path, reusable electronics and replaceable wells. Final cost depends on vendor quotes, print yield, resin consumption, shipping and reusable equipment. Refer to the workbook's formulas and unknown-price fields rather than reusing the preceding wiki's partial total.</p>''','''<p>BOM 分為 STL 列印件、PCB 元件與額外購買材料。已提供的 PCB 報價是兩片共 NT$131,250，包含設計與開機費；NT$65,625 只是這張報價的分攤平均，不是量產單價。不能杜撰濾光片與關鍵材料价格，或為了降低帳面總額而刪除必要功能。</p><p>降低成本的方式是一體風扇座與導流結構、共用氣路、重複使用電子模組與可更換井。最終成本還受廠商報價、列印成功率、樹脂用量、運費及共用設備影響。請使用工作簿的公式與缺價欄，不沿用舊 wiki 的部分總價。</p>''')+f'<div class="downloads">'+''.join(link(p,t) for p,t in [(f'../05_BOM/BOM_{lang}.xlsx',T('Detailed BOM · XLSX','詳細 BOM · XLSX')),(f'../04_manuals/Assembly_Manual_{lang}.pdf',T('Assembly manual · PDF','組裝手冊 · PDF')),(f'../04_manuals/Operation_and_Setup_{lang}.pdf',T('Operation and setup · PDF','操作設定 · PDF')),(f'../04_manuals/Simulation_Analysis_{lang}.pdf',T('Simulation analysis · PDF','模擬分析 · PDF')),('../09_engineering_sources/CAD/aerosense.scad',T('Editable CAD · OpenSCAD','可編輯 CAD · OpenSCAD')),('../02_simulation/optics/run.py',T('Optical simulation and sweep code','光學模擬與掃參數程式')),('../02_simulation/airflow/reproduce.py',T('Airflow reproduction entry point','氣流重現程式入口'))])+ '</div>')
  sec('assembly-usability',T('Usability is the next engineering experiment','把可組裝性當成下一個工程實驗'),T('''<p>The project owner's feedback identified missing access features, too many parts and an assembly manual that was difficult to follow. These are requirements for the redesign, not results of an independent usability study. Engineering Cycle 4 connects those requirements to CAD and computational tests. Cycle 5 will test whether another person can build and operate the reader using the manual.</p><p>Give participants the same parts and instructions. Record assembly completion, time, help requests, wrong orientation, missed seals and well replacement errors; collect clarity and confidence ratings plus specific suggested changes. Report participant count, role, task outcomes and the resulting manual revision. Do not present an unadministered questionnaire as evidence of user satisfaction.</p>''','''<p>專案使用者已指出接孔不足、零件太多，以及組裝手冊難以理解；這些是重新設計的需求，不是獨立使用者研究結果。Engineering Cycle 4 將需求連到 CAD 與計算測試；Cycle 5 則要測試另一個人能否只依手冊完成組裝與操作。</p><p>給參與者相同零件與說明，記錄完成度、時間、求助次數、方向裝錯、漏放密封片與更換井的錯誤，再蒐集清晰度、信心評分與具體修改建議。最後呈現人數、角色、任務結果及手冊因此做出的修改；未施測的問卷不能當作滿意度證據。</p>''')+link(f'../07_validation/User_Feedback_{lang}.pdf',T('Participant feedback form →','使用者回饋表 →'))+' · '+link(f'engineering_cycles_{lang}.html',T('Read the proposed Cycle 4 and Cycle 5 →','閱讀 Cycle 4 與 Cycle 5 內容 →')))
  sec('assembly-readiness',T('Assembly readiness and the next measurement','組裝準備與下一次量測'),T('<p>The base already contains an antenna opening, but the vendor drawing leaves only about0.66 mm nominal clearance during vertical insertion past the upper tongue. Confirm physical module dimensions and print tolerances. All eight STLs and the four wells remain unchanged; mechanical clearance does not establish radio performance.</p><p>The BOM now uses three recalculated batch formulas totaling NT$1,115.39 without adding resin twice. The required non-PCB budget is NTD 14,248.79 (USD 448.00), including a NTD 12,000 custom-filter allowance. It is not an order-ready quotation. The formula results replace the handwritten totals; the source note is preserved.</p><p>Sodium fluorescein is the proposed cell-free standard. It tests optical readout and channel mixing, not gas transport or cell response. A later matched cell comparison must acknowledge the current approximately5-s recording cadence. Keep usability evidence in Hardware and revisions in Engineering; Entrepreneurship or Education may cross-link findings that address their actual objectives.</p>','<p>底座已有天線開口，但依廠商圖，垂直装入通過上緣卡槽的名義餘量只有約0.66 mm，須確認實際模組尺寸與列印公差。八個STL及四井不變；機械間隙不代表無線效能通過。</p><p>BOM已採用三批公式重算列印費NT$1,115.39，不重複加樹脂費。必要非PCB預算為NTD 14,248.79（USD 448.00），包含NTD 12,000客製濾片預留，並非已確認可下單報價。原手填總額不再進目前預算；原始筆記保持不變。</p><p>無細胞標準品建議螢光素鈉，用來測光學讀取與通道混合，不取代氣流或細胞驗證。後續同批細胞比對須承認目前約每5秒一筆的限制。易用性結果留在Hardware，修改放Engineering；Entrepreneurship／Education依實際目的交叉引用。</p>')+'<div class="downloads">'+''.join(link(p,t) for p,t in [(f'../09_engineering_sources/CAD/checks/Antenna_Clearance_{lang}.md',T('Antenna clearance audit','天線間隙查核')),(f'../07_validation/Completion_Plan_{lang}.md',T('Completion checklist','兩週內完成清單')),(f'../07_validation/Fluorescence_and_Cell_Test_{lang}.md',T('Fluorescence and cell comparison','標準液與細胞比對')),(f'../08_reference/Gas_Delivery_Reference_{lang}.md',T('Vergara2012 delivery and drift reference','Vergara2012供氣與漂移引用'))])+'</div>')
  rubric=[(T('Problem and need','問題與需求'),T('Reusable fluorescence acquisition for cell sensors; explain the intended user and workflow.','細胞感測器可重複使用的螢光量測；說明對象與流程。')),(T('Learning from users','從使用者學習'),T('Manual and study plan exist; independent task results are pending.','已有手冊及研究計畫；獨立任務結果待補。')),(T('Demonstrated function','功能證据'),T('Computational and software evidence exist; real-board proof of concept is pending.','已有計算與軟體證據；實板功能證據待補。')),(T('Reproduction by others','他人重現'),T('Publish source, BOM, raw outputs, instructions and limitations together.','一起提供原始碼、BOM、原始結果、步驟與限制。'))]
  sec('validation-boundary',T('One main experiment after essential preflight','必要預檢後，完成一個主要實驗'),T('''<p>After the board arrives, perform a short essential preflight: unpowered fit/leak checks, electrical rails and ADC headroom, dark acquisition, observed LED quadrant mapping and the phone stop command. Stop to troubleshoot clipping, unexpected heating or failed timing QC; correction cannot make invalid data valid.</p><p>Then run one continuous cell-free fluorescence-standard experiment: DARK → illuminated blank calibration → independent held-out blank → one fluorescent well at a time → all wells at half and full concentration → repeated half concentration. Record five distinct valid2-second technical blocks per condition, preserve failures and export the complete JSON. First assembly/flashing is separate; the familiarized experimental sequence is planned for about60–120 minutes, not a promised deadline.</p><p>The three outputs are concentration response, the single-well transfer matrix, and held-out blank before/after correction. Compare the row-normalized matrix with the homogeneous-volume standard model, not the bottom-cell-layer model. This experiment can support fluorescence acquisition, correction and export; it cannot prove gas t90, odor recognition or cell survival. Manual feedback is a separate planned activity, not four additional mandatory studies.</p>''','''<p>PCB到手後先做短時間必要預檢：未通電試裝／漏液、電源與ADC可用範圍、暗訊號、實際LED象限對照，以及手機停止指令。遇到飽和、異常發熱或時序QC失敗就先排除問題；校正不能把無效資料變有效。</p><p>接著只做一個連續的無細胞螢光標準品實驗：暗訊號→亮燈空白校正→獨立保留空白→逐井單獨螢光→全井半濃度及全濃度→重複半濃度。每條件記錄五個不同且有效的兩秒技術區塊，保留失敗並匯出完整JSON。首次組裝／燒錄另計；熟悉操作後此序列規劃約60–120分鐘，不是保證完工時間。</p><p>三張結果圖為濃度響應、單井混合矩陣、保留空白的校正前後比較。矩陣以每列正規化後對照均勻標準液體積模型，不是底部細胞層模型。此實驗可支持螢光擷取、校正與匯出，不能證明氣相t90、氣味識別或細胞存活。手冊回饋另列為待執行活動，不再要求四套額外必做研究。</p>''')+link(f'../07_validation/Validation_Plan_{lang}.md',T('Read the one-experiment procedure →','閱讀單一實驗完整步驟 →'))+' · '+link('../07_validation/quick_check.py',T('Reproducible three-figure analysis','可重現的三圖分析程式'))+f'<h3>{T("Best Hardware evidence map","Best Hardware 證據對照")}</h3>'+table(T(['Judging theme','Evidence and remaining gap'],['評審面向','證據與缺口']),rubric)+T('<p>This map paraphrases the four official Best Hardware ballot themes; it does not invent a separate Overgrad scoring rule. <a href="https://competition.igem.org/judging/special-prizes">Official iGEM Special Prizes</a>.</p>','<p>以上依官方Best Hardware四個評分面向整理，沒有另創Overgrad門檻。<a href="https://competition.igem.org/judging/special-prizes">iGEM官方Special Prizes</a>。</p>')+'<p class="note">'+T('Current evidence is computational design and software checks. PCB function, assembled fit, biological sensing and independent user outcomes still require real data.','目前證據為計算設計與軟體檢查；實板功能、裝件密合、生物感測與獨立使用者結果仍需真實資料。')+'</p>')
  terms=[('DLIA',T('Digital lock-in analysis extracts signal components synchronous with each LED. Same-frequency optical background remains.','數位鎖相分析取出與各 LED 同步的訊號；同頻光學背景仍會留下。')),(T('Calibration','校正'),T('Use measured references to estimate gain, offset, mixing and timing. Preserve raw values and reference IDs.','用實測參考值估計增益、偏移、混合與時序；保留原始值及參考 ID。')),(T('Normalization','正規化'),T('Express a result relative to a defined reference or baseline. It does not repair saturation, drift or missing calibration.','相對於定義好的參考或基線表達結果；不能修復飽和、漂移或未校正資料。')),(T('PD offset','PD 偏心'),T('The light-sensitive region can be displaced from the package center. Mechanical and optical origins must be distinguished.','感光區可能偏離封裝中心，因此機械原點與光學原點要分開。')),(T('Monte Carlo uncertainty','蒙地卡羅不確定性'),T('Finite random packet counts create sampling error. More packets do not remove errors in unknown materials or geometry.','有限光子封包數產生抽樣誤差；增加封包不能消除未知材料或幾何造成的模型誤差。'))]
  sec('glossary',T('Terms used on this page','本頁名詞'),table(T(['Term','Meaning'],['名詞','說明']),terms))
  sec('sources',T('Sources and reproducibility','來源與重現'),'<ul>'+''.join('<li>'+t+'</li>' for t in [link('../02_simulation/optics/Analysis_'+lang+'.md',T('Optical assumptions, full sweep, numerical checks and primary references','光學假設、完整掃參數、數值檢查與原始文獻')),link('../02_simulation/airflow/Airflow_Analysis_'+lang+'.md',T('Gas model, mesh refinement, rankings and limitations','氣流模型、網格細化、排名與限制')),link('../02_simulation/optics/results/summary.json',T('Optical primary summary · JSON','光學主要摘要 · JSON')),link('../02_simulation/airflow/selection.json',T('Final gas-path selection · JSON','最終氣路選擇 · JSON')),link('../03_software/README_'+lang+'.md',T('Software source, build and test evidence','軟體原始碼、建置與測試證據')),link('https://www.pnas.org/doi/10.1073/pnas.1920073117','Burton et al., PNAS (2020), doi:10.1073/pnas.1920073117'),link('https://competition.igem.org/judging/special-prizes',T('iGEM · official Best Hardware judging themes','iGEM · 官方 Best Hardware 評審面向'))])+'</ul>')
  sec('publication-drafts',T('Three page drafts and their placement','三個頁面的草稿與放置規劃'),'<div class="downloads">'+''.join(link(f'content_plan/{name}_{lang}.md',T(enlabel,zhlabel)) for name,enlabel,zhlabel in [('Description_Sections','Description: project need and concept','Description：需求與概念'),('Hardware_Sections','Hardware: design and operating evidence','Hardware：設計與操作證據'),('Model_Sections','Model: assumptions and quantitative studies','Model：假設與定量研究'),('Placement_Plan','Page placement and integration plan','頁面放置與整合計畫')])+'</div>'+T('<p>These are local editorial drafts. Keep computational predictions, planned experiments and measured results distinct; nothing has been uploaded.</p>','<p>以上是本機內容草稿；計算預測、規劃實驗與實測結果必須分開標示，尚未上傳網站。</p>'))
  sections.append(simulation_supplement(ROOT,lang))
  doc=f'<!doctype html><html lang="{"en" if en else "zh-Hant"}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>{STYLE}</style></head><body><header><div class="eyebrow">AEROSENSE / HARDWARE / ENGINEERING</div><h1>{title}</h1><p>{T("One evidence trail: requirements → geometry → computation → bench tests → user feedback.","同一條證據鏈：需求 → 幾何 → 計算 → 實測 → 使用者回饋。")}</p><span class="status">{T("Populated-board dimensions and physical validation pending","實板尺寸與實體驗證待確認")}</span><p>{link("hardware_"+("ZH" if en else "EN")+".html",T("繁體中文","English"))}</p></header><nav>'+''.join(link('#'+i,t) for i,t in [('mechanical-package',T('Design','設計')),('reader-assembly',T('STLs','STL')),('optical-question',T('Optics','光學')),('gas-operation',T('Gas flow','氣流')),('electronics-bridge',T('Control','控制')),('cost-and-reproduction',T('Downloads','下載')),('validation-boundary',T('Evidence','證據'))])+'</nav><main>'+''.join(sections)+'</main><footer>'+T('Local publication draft. Links target this reproducibility package; follow the integration map before uploading to the team wiki.','本機發布草稿；連結指向此重現資料包，移至團隊 wiki 前請依整合對照表調整。')+'</footer></body></html>'
